app.post('/webhooks/stripe', express.raw({type:'application/json'}), (req, res) => {
  const sig = req.headers['stripe-signature'];
  let event;
  try {
    // 원본 본문(raw) + 비밀키로 서명 검증 — 위조·변조면 예외
    event = stripe.webhooks.constructEvent(req.body, sig, WEBHOOK_SECRET);
  } catch (err) {
    return res.status(400).send('서명 검증 실패');  // 거부 — 처리 안 함
  }
  // 여기부터만 event 를 신뢰 (진짜 PG·변조 없음)
  ...
});
// 주의: 서명 검증은 원본(raw) 본문으로 — JSON 파싱 후엔 바이트가 달라져 실패

async function handleEvent(event) {
  // 이 event id 를 이미 처리했나? (고유 제약으로 원자적 확인)
  const already = await db.processedEvents.exists(event.id);
  if (already) return;                        // 이미 처리 → 건너뛰기(중복 방지)

  await db.transaction(async (tx) => {
    await 상품지급(tx, event);                 // 실제 처리
    await tx.processedEvents.insert(event.id);  // 처리 완료 기록(같은 트랜잭션)
  });
  // 처리와 기록이 한 트랜잭션 → 처리했으면 기록도 됨(원자성, pay-idem)
}
// 웹훅은 at-least-once — 같은 이벤트가 여러 번 올 수 있으니 멱등 필수
